-- Rank chains (Deadly Poison's script, spell_rog_deadly_poison, is registered on its chain)
DELETE FROM `spell_ranks` WHERE `spell_id` IN (920006, 920007, 920008, 920009, 920010, 920011, 920012, 920013, 920014, 920015, 920016, 920017, 920018, 920019, 920020, 920022, 920023, 920024, 920025, 920101, 920102, 920103, 920104, 920111, 920112, 920113, 920114, 920121, 920122, 920123, 920124, 920131, 920132, 920133, 920134, 920201, 920202, 920203, 920204, 920211, 920212, 920213, 920214, 920221, 920222, 920223, 920224, 920231, 920232, 920233, 920234, 920301, 920302, 920303, 920304, 920311, 920312, 920313, 920314, 920321, 920322, 920323, 920324, 920331, 920332, 920333, 920334, 920341, 920342, 920343, 920344, 920351, 920352, 920353, 920354);
INSERT INTO `spell_ranks` (`first_spell_id`, `spell_id`, `rank`) SELECT `r`.`first_spell_id`, `m`.`new_id`, `r`.`rank` + `m`.`step` FROM `dc_tmp_class_item_map` AS `m` JOIN `spell_ranks` AS `r` ON `r`.`spell_id` = `m`.`old_id`;

-- Attack power coefficients of the poisons: by the spell's own id, else by its first rank's
DELETE FROM `spell_bonus_data` WHERE `entry` IN (920006, 920007, 920008, 920009, 920010, 920011, 920012, 920013, 920014, 920015, 920016, 920017, 920018, 920019, 920020, 920022, 920023, 920024, 920025, 920101, 920102, 920103, 920104, 920111, 920112, 920113, 920114, 920121, 920122, 920123, 920124, 920131, 920132, 920133, 920134, 920201, 920202, 920203, 920204, 920211, 920212, 920213, 920214, 920221, 920222, 920223, 920224, 920231, 920232, 920233, 920234, 920301, 920302, 920303, 920304, 920311, 920312, 920313, 920314, 920321, 920322, 920323, 920324, 920331, 920332, 920333, 920334, 920341, 920342, 920343, 920344, 920351, 920352, 920353, 920354);
INSERT INTO `spell_bonus_data` (`entry`, `direct_bonus`, `dot_bonus`, `ap_bonus`, `ap_dot_bonus`, `comments`) SELECT `m`.`new_id`, `b`.`direct_bonus`, `b`.`dot_bonus`, `b`.`ap_bonus`, `b`.`ap_dot_bonus`, `b`.`comments` FROM `dc_tmp_class_item_map` AS `m` JOIN `spell_ranks` AS `r` ON `r`.`spell_id` = `m`.`old_id` JOIN `spell_bonus_data` AS `b` ON `b`.`entry` = CASE WHEN EXISTS (SELECT 1 FROM `spell_bonus_data` AS `o` WHERE `o`.`entry` = `m`.`old_id`) THEN `m`.`old_id` ELSE `r`.`first_spell_id` END;

